# v0.7.5 P0.68 — Faker Tier-2 restoration (reinstated after v0.6.8 removal).
# Faker is a pure-Python pip dependency that works in Databricks Serverless
# where pip install is allowed. It sits between Tier 1 (LLM pool-spec) and
# Tier 3 (stdlib-random) and provides realistic values for well-known column
# semantics (email, phone, address, name, uuid, url, etc.). If Faker is not
# installed we gracefully fall back to stdlib-random; no crash.
try:
    from faker import Faker as _P068_Faker  # type: ignore
    _FAKER_AVAILABLE = True
    _FAKER_INSTANCE = _P068_Faker()
    try:
        _FAKER_INSTANCE.seed_instance(42)  # deterministic smoke seed
    except Exception:
        pass
except Exception:  # ImportError or any transient Faker-init failure
    _FAKER_AVAILABLE = False
    _FAKER_INSTANCE = None


# v0.7.6 P0.83 — run-scoped counter for raw-pool-spec logs. Capped at 3 so
# we don't spam the driver log. Reset is implicit via process restart.
_P083_RAW_LOG_COUNT = 0

# === CELL 4: Utility Functions & Validators ===
def _p083_emit_raw_pool_log(product_name, raw_text, logger):
    """Emit the first 200 chars of a raw pool-spec response. Module-level so
    the nested sample helper can call it without closure gymnastics. Capped
    at 3 logs per process run so we don't spam the driver log.
    Databricks Serverless compatible (stdlib only).
    """
    global _P083_RAW_LOG_COUNT
    try:
        if _P083_RAW_LOG_COUNT >= 3:
            return
        _P083_RAW_LOG_COUNT += 1
        _preview = (str(raw_text or "")[:200]).replace('\n', ' ')
        logger.warning(
            f"[P0.83-POOL-RAW] product={product_name} first_200_chars={_preview!r}"
        )
    except Exception:
        pass


# v0.7.5 P0.68 — Faker provider map keyed by tuple of column-name tokens.
# Each value is a (provider_name, lambda) pair so we can log the provider
# we chose. Keys are matched via `_is_pii_match`'s tokenized word-boundary
# semantics (shared from P0.73) so that 'customer_email' matches ('email',)
# but 'MARKETING_OPT_IN' does NOT falsely match ('tin',) if any tin-like
# token pattern were ever added. Industry-agnostic — no vertical-specific
# providers.
def _p068_faker_provider_map():
    """Returns an ordered list of (token_tuple, provider_name, callable) rows.
    Ordering matters: more specific multi-token patterns come first so that
    ('customer_name',) wins over ('name',) even though both would match.
    """
    F = _FAKER_INSTANCE
    if F is None:
        return []
    # ORDERING RULE: multi-token / more-specific patterns MUST precede their
    # single-token supersets. E.g. ('ip_address',) must come before
    # ('address',) so 'ip_address' routes to faker.ipv4 not faker.street_address.
    return [
        # --- tech identifiers (specific) ---
        (("ip_address",),             "faker.ipv4",          lambda: F.ipv4()),
        (("ipv4",),                   "faker.ipv4",          lambda: F.ipv4()),
        (("user_agent",),             "faker.user_agent",    lambda: F.user_agent()),
        (("uuid",),                   "faker.uuid4",         lambda: str(F.uuid4())),
        (("guid",),                   "faker.uuid4",         lambda: str(F.uuid4())),
        # --- url / website ---
        (("url",),                    "faker.url",           lambda: F.url()),
        (("website",),                "faker.url",           lambda: F.url()),
        # --- name-like (multi-token first) ---
        (("full_name",),              "faker.name",          lambda: F.name()),
        (("customer_name",),          "faker.name",          lambda: F.name()),
        (("user_name",),              "faker.user_name",     lambda: F.user_name()),
        (("first_name",),             "faker.first_name",    lambda: F.first_name()),
        (("last_name",),              "faker.last_name",     lambda: F.last_name()),
        (("middle_name",),            "faker.first_name",    lambda: F.first_name()),
        # --- contact ---
        (("email",),                  "faker.email",         lambda: F.email()),
        (("phone_number",),           "faker.phone_number",  lambda: F.phone_number()),
        (("phone",),                  "faker.phone_number",  lambda: F.phone_number()),
        (("mobile",),                 "faker.phone_number",  lambda: F.phone_number()),
        (("cell",),                   "faker.phone_number",  lambda: F.phone_number()),
        # --- address (street_* more specific than bare 'address') ---
        (("street_address",),         "faker.street_address",lambda: F.street_address()),
        (("street_name",),             "faker.street_name",  lambda: F.street_name()),
        (("address",),                "faker.street_address",lambda: F.street_address()),
        (("street",),                 "faker.street_name",   lambda: F.street_name()),
        (("postal_code",),            "faker.postcode",      lambda: F.postcode()),
        (("zip_code",),               "faker.postcode",      lambda: F.postcode()),
        (("postal",),                 "faker.postcode",      lambda: F.postcode()),
        (("zip",),                    "faker.postcode",      lambda: F.postcode()),
        (("city",),                   "faker.city",          lambda: F.city()),
        (("state",),                  "faker.state",         lambda: F.state()),
        (("country",),                "faker.country",       lambda: F.country()),
        # --- company / role ---
        (("company_name",),           "faker.company",       lambda: F.company()),
        (("company",),                "faker.company",       lambda: F.company()),
        (("job_title",),              "faker.job",           lambda: F.job()),
        (("title",),                  "faker.job",           lambda: F.job()),
        # --- text blobs ---
        (("description",),            "faker.sentence",      lambda: F.sentence()),
        (("notes",),                  "faker.paragraph",     lambda: F.paragraph(nb_sentences=2)),
        (("comment",),                "faker.paragraph",     lambda: F.paragraph(nb_sentences=2)),
        # --- finance / locale ---
        (("currency_code",),          "faker.currency_code", lambda: F.currency_code()),
        (("locale",),                 "faker.locale",        lambda: F.locale()),
    ]


_P068_FAKER_PROVIDERS = _p068_faker_provider_map() if _FAKER_AVAILABLE else []


def _p068_pick_faker_provider(column_name, col_tokens=None):
    """v0.7.5 P0.68: choose a Faker provider for a column.

    Reuses P0.73's `_p073_tokenize` and the contiguous-subsequence semantics
    of `_is_pii_match` for DRY — same word-boundary algorithm, no duplicate
    tokenizer.

    Returns (provider_name:str, callable) on match, else (None, None).

    Ordering: first entry in _P068_FAKER_PROVIDERS whose token-tuple is a
    contiguous subsequence of `column_name`'s tokens wins. The provider
    map's token tuples may themselves contain multi-token strings
    (e.g. ('first_name',) means "first" + "name"); we re-tokenize each
    entry through _p073_tokenize so the match semantics match column
    semantics exactly.
    """
    if not _FAKER_AVAILABLE or not _P068_FAKER_PROVIDERS:
        return (None, None)
    if col_tokens is None:
        col_tokens = _p073_tokenize(column_name)
    if not col_tokens:
        return (None, None)
    col_tokens_lc = [t.lower() for t in col_tokens]
    n_tokens = len(col_tokens_lc)
    for token_tuple, provider_name, fn in _P068_FAKER_PROVIDERS:
        # Re-tokenize the pattern so ("first_name",) becomes ["first","name"],
        # matching how _p073_tokenize splits column names.
        pt = []
        for piece in token_tuple:
            pt.extend(_p073_tokenize(piece))
        m = len(pt)
        if m == 0 or m > n_tokens:
            continue
        pt_lc = [t.lower() for t in pt]
        for i in range(0, n_tokens - m + 1):
            if col_tokens_lc[i:i + m] == pt_lc:
                return (provider_name, fn)
    return (None, None)


from contextlib import contextmanager

_suppress_stdout_lock = threading.RLock()

def _io_with_timeout(fn, timeout_s, logger=None, label="io"):
    # v3.6.2 alias=io-timeout-watchdog: run a potentially-blocking I/O call (UC Volume
    # rm/mkdirs/put/SDK-upload) in a daemon worker thread and join() with a hard deadline.
    # Serverless dbutils.fs / Files-API calls have NO client-side timeout, so a stalled
    # volume blocks the caller forever (root cause of the new-base-model silent hang). The
    # main thread proceeds after the deadline; an abandoned worker is daemon and dies with
    # the process. Returns (value, timed_out).
    import threading as _iot
    _box = {"done": False, "val": None, "exc": None}
    def _run():
        try:
            _box["val"] = fn()
        except BaseException as _e:
            _box["exc"] = _e
        finally:
            _box["done"] = True
    _t = _iot.Thread(target=_run, name=f"io-timeout-{label}", daemon=True)
    _t.start()
    _t.join(timeout_s)
    if not _box["done"]:
        if logger is not None:
            try:
                logger.warning(f"  [io-timeout-watchdog FIRED v3.6.2] '{label}' exceeded {timeout_s}s — not waiting; main thread proceeds (daemon worker abandoned) alias=io-timeout-watchdog")
            except Exception:
                pass
        return None, True
    if _box["exc"] is not None:
        raise _box["exc"]
    return _box["val"], False


@contextmanager
def _suppress_dbutils_stdout():
    acquired = _suppress_stdout_lock.acquire(timeout=30)
    if not acquired:
        yield
        return
    _orig = sys.stdout
    sys.stdout = io.StringIO()
    try:
        yield
    finally:
        sys.stdout = _orig
        _suppress_stdout_lock.release()


def _flush_log_handlers(logger):
    try:
        for h in getattr(logger, 'handlers', []):
            h.flush()
    except Exception:
        pass
    try:
        sys.stdout.flush()
        sys.stderr.flush()
    except Exception:
        pass


def _fmt_hms(seconds):
    s = int(seconds)
    h, rem = divmod(s, 3600)
    m, sec = divmod(rem, 60)
    if h > 0:
        return f"{h:02d}:{m:02d}:{sec:02d}"
    return f"{m:02d}:{sec:02d}"


def _format_eta(elapsed_secs, completed, total):
    if completed <= 0 or elapsed_secs <= 0:
        return "calculating..."
    rate = completed / elapsed_secs
    remaining = (total - completed) / rate
    return _fmt_hms(remaining)



def _remove_stream_handlers(log_obj):
    for h in list(log_obj.handlers):
        if isinstance(h, logging.StreamHandler):
            log_obj.removeHandler(h)

