    'SUM','AVG','COUNT','MIN','MAX','MEAN','STDDEV','VARIANCE','PERCENTILE','MEDIAN',
    'FIRST','LAST','DISTINCT','APPROX_COUNT_DISTINCT','ANY_VALUE','COLLECT_LIST','COLLECT_SET',
