                        _nv_elapsed = time.time() - nv_start
                        logger.info(f"--- [Parallel] ✅ Next vibe generation completed in {format_duration(_nv_elapsed)} ---")
                        _vw_nv_ok = widgets_values.get("vibe_writer")
