# ═══════════════════════════════════════════════════════════════════
# v0.7.0 P0.27 — Standalone sanity harness for sample helpers.
# Mirrors the nested helpers inside `_generate_and_insert_samples_for_product`
# so we can smoke-test each bucket WITHOUT spinning up a Spark session.
# Guarded by `if False:` so it stays inert at import; flip the guard when
# you want to run the smoke check from a Databricks cell or CLI.
# ═══════════════════════════════════════════════════════════════════

def _sample_helpers_sanity_check():  # v0.7.0 P0.27
    """Exercise every sample-generation bucket and assert expected Python types.

    IMPORTANT: this harness re-implements the nested helpers (`_sample_temporal`,
    `_sample_numeric`, `_sample_boolean`, `_sample_pool`, `_assemble_rows_from_pools`)
    AS THEY LIVE INSIDE `_generate_and_insert_samples_for_product`. If you change
    one side, change the other — intentional duplication keeps the smoke check
    free of Spark/Databricks coupling.
    """
    import random as _rnd_mod
    from datetime import datetime as _dt, timedelta as _td, date as _date
    from decimal import Decimal as _Dec

    _RANGE_HINT_DAYS = {
        'last_1y':  (-365, 0),
        'last_3y':  (-3 * 365, 0),
        'last_5y':  (-5 * 365, 0),
        'last_10y': (-10 * 365, 0),
        'next_6m':  (0, 183),
        'next_1y':  (0, 365),
        'next_3y':  (0, 3 * 365),
        'hist_10y_weighted_recent': (-10 * 365, 0),
    }

    def _type_is_int(atype):
        return ('BIGINT' in atype) or ('INT' in atype) or ('LONG' in atype)

    def _coerce_num(v, default):
        try:
            return float(v)
        except (TypeError, ValueError):
            return float(default)

    # ---- mirrors of the in-product helpers -----------------------------------
    def _sample_temporal(range_hint, atype, sample_count, rnd, *_unused):
        lo, hi = _RANGE_HINT_DAYS.get(str(range_hint or '').strip(), (-3 * 365, 0))
        now = _dt.now()
        values = []
        _wr = (str(range_hint or '').strip() == 'hist_10y_weighted_recent')
        for _ in range(sample_count):
            if _wr:
                if rnd.random() < 0.7:
                    delta = rnd.randint(-2 * 365, 0)
                else:
                    delta = rnd.randint(lo, hi)
            else:
                delta = rnd.randint(lo, hi)
            dt = now + _td(days=delta)
            if 'TIMESTAMP' in atype:
                dt = dt.replace(hour=rnd.randint(0, 23), minute=rnd.randint(0, 59),
                                second=rnd.randint(0, 59), microsecond=0)
                values.append(dt)
            elif 'DATE' in atype:
                values.append(dt.date())
            else:
                values.append(dt.date().isoformat())
        return values

    def _sample_numeric(spec, atype, sample_count, rnd):
        lo = _coerce_num(spec.get('min', 0), 0)
        hi = _coerce_num(spec.get('max', 1000), 1000)
        if hi <= lo:
            hi = lo + 1
        try:
            scale = int(spec.get('scale', 2))
        except (TypeError, ValueError):
            scale = 2
        scale = max(0, min(6, scale))
        _up = (atype or "").upper()
        is_int = any(k in _up for k in ('BIGINT', 'INT', 'LONG', 'SMALLINT', 'TINYINT'))
        is_double_or_float = (('DOUBLE' in _up) or ('FLOAT' in _up)) and ('DECIMAL' not in _up)
        is_decimal = ('DECIMAL' in _up) or ('NUMERIC' in _up)
        out = []
        for _ in range(sample_count):
            if is_int:
                lo_i, hi_i = int(lo), int(hi)
                if hi_i <= lo_i:
                    hi_i = lo_i + 1
                out.append(rnd.randint(lo_i, hi_i))
            elif is_double_or_float:
                if scale > 0:
                    out.append(round(rnd.uniform(float(lo), float(hi)), scale))
                else:
                    out.append(rnd.uniform(float(lo), float(hi)))
            elif is_decimal:
                if scale > 0:
                    mult = 10 ** scale
                    lo_s = int(round(lo * mult))
                    hi_s = int(round(hi * mult))
                    if hi_s <= lo_s:
                        hi_s = lo_s + 1
                    raw = rnd.randrange(lo_s, hi_s + 1)
                    out.append(_Dec(raw) / _Dec(mult))
                else:
                    out.append(_Dec(rnd.randint(int(lo), int(hi))))
            else:
                out.append(rnd.uniform(float(lo), float(hi)))
        return out

    def _format_boolean(b, boolean_format):
        bf = str(boolean_format or '').lower()
        if 'int' in bf or '0/1' in bf:
            return 1 if b else 0
        if 'y/n' in bf or 'string' in bf:
            return 'Y' if b else 'N'
        return bool(b)

    def _sample_boolean(p_true, sample_count, rnd, boolean_format, atype):
        try:
            p = float(p_true)
        except (TypeError, ValueError):
            p = 0.5
        p = max(0.0, min(1.0, p))
        if 'BOOLEAN' in atype:
            return [rnd.random() < p for _ in range(sample_count)]
        return [_format_boolean(rnd.random() < p, boolean_format) for _ in range(sample_count)]

    def _sample_pool(pool, weights, sample_count, rnd):
        if not pool:
            return [None] * sample_count
        if weights and len(weights) == len(pool):
            try:
                wsum = float(sum(weights))
                if 0.5 < wsum < 2.0:
                    return [rnd.choices(pool, weights=weights, k=1)[0] for _ in range(sample_count)]
            except (TypeError, ValueError):
                pass
        return [rnd.choice(pool) for _ in range(sample_count)]

    # ---- assertion utilities -------------------------------------------------
    _errors = []

    def _check(cond, msg):
        if not cond:
            _errors.append(msg)
            print(f"  [P0.27 FAIL] {msg}")
        else:
            print(f"  [P0.27 OK ] {msg}")

    rnd = _rnd_mod.Random(4242)  # deterministic seed

    # ---- exercise _sample_temporal across ALL range hints --------------------
    for _hint in _RANGE_HINT_DAYS.keys():
        _vals_ts = _sample_temporal(_hint, 'TIMESTAMP', 3, rnd)
        _check(all(isinstance(v, _dt) for v in _vals_ts),
               f"_sample_temporal TIMESTAMP with hint={_hint} → datetime values")
        _vals_dt = _sample_temporal(_hint, 'DATE', 3, rnd)
        _check(all(isinstance(v, _date) and not isinstance(v, _dt) for v in _vals_dt),
               f"_sample_temporal DATE with hint={_hint} → date values")

    # ---- exercise _sample_numeric across all declared types ------------------
    _num_cases = [
        ('BIGINT',         {'min': 1, 'max': 1000},               int,     False),
        ('INT',            {'min': 0, 'max': 100},                int,     False),
        ('DECIMAL(10,2)',  {'min': 0, 'max': 50,  'scale': 2},    _Dec,    False),
        ('DOUBLE',         {'min': 0, 'max': 50,  'scale': 2},    float,   False),
        ('FLOAT',          {'min': 0, 'max': 50,  'scale': 2},    float,   False),
    ]
    for _atype, _spec, _expected, _ignored in _num_cases:
        _vals = _sample_numeric(_spec, _atype, 5, rnd)
        _check(len(_vals) == 5,
               f"_sample_numeric {_atype} returns requested count")
        _check(all(isinstance(v, _expected) for v in _vals),
               f"_sample_numeric {_atype} → {_expected.__name__} (got {[type(v).__name__ for v in _vals]})")

    # ---- exercise _sample_boolean with probabilities × widget formats --------
    _probs = [0.0, 0.5, 1.0]
    _widgets = ['Boolean (True/False)', 'Integer (1/0)', 'Y/N String']
    for _p in _probs:
        # atype=BOOLEAN → always bool regardless of widget
        _vals = _sample_boolean(_p, 10, rnd, 'Boolean (True/False)', 'BOOLEAN')
        _check(all(isinstance(v, bool) for v in _vals),
               f"_sample_boolean p={_p} atype=BOOLEAN → python bool")
        # atype=STRING-ish (non-BOOLEAN) → widget decides
        for _w in _widgets:
            _vals_w = _sample_boolean(_p, 10, rnd, _w, 'STRING')
            _expected_types = {
                'Boolean (True/False)': bool,
                'Integer (1/0)': int,
                'Y/N String': str,
            }[_w]
            _check(all(isinstance(v, _expected_types) for v in _vals_w),
                   f"_sample_boolean p={_p} widget={_w!r} atype=STRING → {_expected_types.__name__}")

    # ---- exercise _sample_pool with and without weights ----------------------
    _pool = ['a', 'b', 'c', 'd', 'e']
    _vals_uniform = _sample_pool(_pool, None, 20, rnd)
    _check(len(_vals_uniform) == 20 and all(v in _pool for v in _vals_uniform),
           "_sample_pool uniform (no weights)")
    _vals_w = _sample_pool(_pool, [0.5, 0.2, 0.1, 0.1, 0.1], 20, rnd)
    _check(len(_vals_w) == 20 and all(v in _pool for v in _vals_w),
           "_sample_pool weighted")

    # ---- end-to-end _assemble_rows_from_pools with 3-column minimal schema ---
    # Build a flat mock fb_col_info that the assembler expects.
    _fb_col_info = [
        {'col_name': 'id',         'attr_type': 'BIGINT',        'is_pk': True,  'is_fk': False, 'is_self_ref_fk': False, 'attr_meta': {}},
        {'col_name': 'price',      'attr_type': 'DECIMAL(10,2)', 'is_pk': False, 'is_fk': False, 'is_self_ref_fk': False, 'attr_meta': {}},
        {'col_name': 'status',     'attr_type': 'STRING',        'is_pk': False, 'is_fk': False, 'is_self_ref_fk': False, 'attr_meta': {}},
    ]
    _pool_spec = {
        'columns': {
            'price':  {'bucket': 'numeric',     'min': 1, 'max': 100, 'scale': 2},
            'status': {'bucket': 'categorical', 'pool': ['active', 'inactive', 'pending', 'expired', 'archived']},
        }
    }

    # Minimal re-implementation of _assemble_rows_from_pools (product-local variant).
    def _assemble_rows_from_pools(pool_spec, sample_count, fb_col_info, *_unused):
        rnd2 = _rnd_mod.Random(99)
        columns_spec = (pool_spec or {}).get('columns') or {}
        col_values = {}
        for ci in fb_col_info:
            name = ci['col_name']
            atype = ci['attr_type']
            if ci['is_pk']:
                col_values[name] = [10001 + i for i in range(sample_count)]
                continue
            spec = columns_spec.get(name) or {}
            bucket = str(spec.get('bucket', '')).lower()
            if bucket == 'numeric':
                col_values[name] = _sample_numeric(spec, atype, sample_count, rnd2)
            elif bucket in ('categorical', 'freetext'):
                col_values[name] = _sample_pool(spec.get('pool') or [], spec.get('weights'), sample_count, rnd2)
            else:
                col_values[name] = [None] * sample_count
        rows = []
        for r in range(sample_count):
            rows.append(tuple(col_values[ci['col_name']][r] for ci in fb_col_info))
        return rows

    _rows = _assemble_rows_from_pools(_pool_spec, 4, _fb_col_info)
    _check(len(_rows) == 4, "_assemble_rows_from_pools row count")
    _check(all(isinstance(r, tuple) and len(r) == 3 for r in _rows),
           "_assemble_rows_from_pools tuple shape (3 cols)")
    _check(all(isinstance(r[0], int) for r in _rows),
           "_assemble_rows_from_pools PK column is int (BIGINT)")
    _check(all(isinstance(r[1], _Dec) for r in _rows),
           "_assemble_rows_from_pools DECIMAL column emits Decimal")
    _check(all(isinstance(r[2], str) and r[2] in ('active','inactive','pending','expired','archived') for r in _rows),
           "_assemble_rows_from_pools categorical STRING column")

    print(f"\n[P0.27] Sanity check complete — {len(_errors)} error(s)")
    return len(_errors) == 0


if False:  # v0.7.0 P0.27 — flip to True to run the sample-helper smoke check.
    _sample_helpers_sanity_check()


