# ═══════════════════════════════════════════════════════════════════
# v0.7.6 P0.83 sanity harness — pool-spec parser resilience.
# ═══════════════════════════════════════════════════════════════════
def _p083_pool_parse_sanity_check():
    """v0.7.6 P0.83: verify the pool-spec parser accepts multiple LLM-response
    shapes that previously failed 100% of the time.

    SHAPES TESTED:
      (A) Canonical {columns: {col: {bucket, pool}}} — must pass.
      (B) Array of column objects — must normalise into canonical shape.
      (C) {columns: [...]} array variant — must normalise.
      (D) `pool_type` / `values` aliases — must remap.
      (E) Single-quoted JSON — must fall back and parse.
      (F) Markdown-fenced JSON — must strip fences.
      (G) Genuinely-unparseable prose — must return None, not crash.

    Mirrors the in-step-local `_parse_pool_json`, but we call a module-level
    stand-in that replicates the logic byte-for-byte.
    """
    failures = []

    # Re-implement the parser inline so the harness is hermetic (mirrors the
    # inside-step version exactly). If you change the in-step parser, mirror
    # the change here — the intentional duplication keeps the harness
    # independent of Spark/Databricks plumbing.
    def _parse_pool_json(raw_text):
        if not raw_text or not isinstance(raw_text, str):
            return None
        txt = raw_text.strip()
        if txt.startswith("```"):
            lines = txt.split('\n')
            if lines and lines[0].startswith("```"):
                lines = lines[1:]
            if lines and lines[-1].strip() == "```":
                lines = lines[:-1]
            txt = '\n'.join(lines).strip()
        _first_obj = txt.find('{')
        _first_arr = txt.find('[')
        _first = -1
        _last = -1
        _is_array = False
        if _first_obj != -1 and (_first_arr == -1 or _first_obj < _first_arr):
            _first = _first_obj
            _last = txt.rfind('}')
            _is_array = False
        elif _first_arr != -1:
            _first = _first_arr
            _last = txt.rfind(']')
            _is_array = True
        if _first == -1 or _last == -1 or _last <= _first:
            return None
        candidate = txt[_first:_last + 1]
        parsed = None
        try:
            parsed = json.loads(candidate)
        except Exception:
            try:
                parsed = json.loads(candidate.replace("'", '"'))
            except Exception:
                return None

        def _norm_col_entry(entry):
            if not isinstance(entry, dict):
                return None
            out = dict(entry)
            if 'bucket' not in out:
                if 'pool_type' in out:
                    out['bucket'] = out.pop('pool_type')
                elif 'type' in out and isinstance(out.get('type'), str):
                    out['bucket'] = out.pop('type')
            _bk = str(out.get('bucket', '') or '').strip().lower()
            if _bk == 'identifier':
                _bk = 'categorical'
            elif _bk in ('enum', 'enumeration', 'enumerated'):
                _bk = 'categorical'
            elif _bk in ('string', 'freeform', 'text'):
                _bk = 'freetext'
            out['bucket'] = _bk
            if 'pool' not in out and 'values' in out:
                out['pool'] = out.pop('values')
            return out

        if _is_array:
            cols = {}
            for _e in parsed:
                if not isinstance(_e, dict):
                    continue
                _cn = _e.get('column_name') or _e.get('name') or _e.get('column')
                if not _cn or not isinstance(_cn, str):
                    continue
                _ne = _norm_col_entry(_e)
                if _ne:
                    cols[_cn] = _ne
            if not cols:
                return None
            return {"columns": cols}
        if not isinstance(parsed, dict):
            return None
        _ci_top = {}
        for _tk, _tv in parsed.items():
            _kl = str(_tk).strip().lower()
            if _kl in ('columns', 'correlated_groups') and _kl not in _ci_top:
                _ci_top[_kl] = _tv
        if _ci_top:
            _new_parsed = {k: v for k, v in parsed.items() if str(k).strip().lower() not in ('columns', 'correlated_groups')}
            _new_parsed.update(_ci_top)
            parsed = _new_parsed
        _cols_raw = parsed.get('columns')
        if isinstance(_cols_raw, list):
            cols = {}
            for _e in _cols_raw:
                if not isinstance(_e, dict):
                    continue
                _cn = _e.get('column_name') or _e.get('name') or _e.get('column')
                if not _cn or not isinstance(_cn, str):
                    continue
                _ne = _norm_col_entry(_e)
                if _ne:
                    cols[_cn] = _ne
            parsed = {**parsed, 'columns': cols}
        elif isinstance(_cols_raw, dict):
            cols = {}
            for _cn, _e in _cols_raw.items():
                if isinstance(_e, dict):
                    _ne = _norm_col_entry(_e)
                    if _ne:
                        cols[_cn] = _ne
            parsed = {**parsed, 'columns': cols}
        else:
            _maybe_cols = {}
            for _k, _v in parsed.items():
                if _k in ('columns', 'correlated_groups'):
                    continue
                if isinstance(_v, dict) and ('bucket' in _v or 'pool_type' in _v or 'type' in _v):
                    _ne = _norm_col_entry(_v)
                    if _ne:
                        _maybe_cols[_k] = _ne
            if _maybe_cols:
                parsed = {"columns": _maybe_cols,
                          **({"correlated_groups": parsed["correlated_groups"]}
                             if isinstance(parsed.get("correlated_groups"), list) else {})}
            else:
                return None
        if not parsed.get('columns'):
            return None
        return parsed

    # (A) Canonical shape.
    _a = _parse_pool_json('{"columns": {"status": {"bucket": "categorical", "pool": ["a","b","c","d","e"]}}}')
    if not (_a and _a.get("columns", {}).get("status", {}).get("bucket") == "categorical"):
        failures.append(f"P0.83 (A) canonical failed: {_a}")

    # (B) Array shape.
    _b_raw = '[{"column_name": "status", "pool_type": "categorical", "values": ["a","b","c"]}]'
    _b = _parse_pool_json(_b_raw)
    if not (_b and _b.get("columns", {}).get("status", {}).get("bucket") == "categorical"):
        failures.append(f"P0.83 (B) array shape failed: {_b}")
    if not (_b and _b.get("columns", {}).get("status", {}).get("pool") == ["a", "b", "c"]):
        failures.append(f"P0.83 (B) pool alias not remapped: {_b}")

    # (C) {columns: [...]} array variant.
    _c_raw = '{"columns": [{"column_name": "status", "pool_type": "categorical", "pool": ["x","y","z"]}]}'
    _c = _parse_pool_json(_c_raw)
    if not (_c and _c.get("columns", {}).get("status", {}).get("pool") == ["x", "y", "z"]):
        failures.append(f"P0.83 (C) {{columns: [...]}} failed: {_c}")

    # (D) pool_type alias, categorical-ish `type` field.
    _d_raw = '{"columns": {"foo": {"type": "enum", "pool": ["1","2","3","4","5"]}}}'
    _d = _parse_pool_json(_d_raw)
    if not (_d and _d.get("columns", {}).get("foo", {}).get("bucket") == "categorical"):
        failures.append(f"P0.83 (D) enum→categorical failed: {_d}")

    # (E) Single-quote JSON.
    _e = _parse_pool_json("{'columns': {'status': {'bucket': 'categorical', 'pool': ['a','b','c']}}}")
    if not (_e and _e.get("columns", {}).get("status", {}).get("bucket") == "categorical"):
        failures.append(f"P0.83 (E) single-quote JSON failed: {_e}")

    # (F) Markdown fences.
    _f_raw = '```json\n{"columns": {"status": {"bucket": "categorical", "pool": ["a","b","c"]}}}\n```'
    _f = _parse_pool_json(_f_raw)
    if not (_f and _f.get("columns", {}).get("status", {}).get("bucket") == "categorical"):
        failures.append(f"P0.83 (F) markdown fences failed: {_f}")

    # (G) Unparseable prose.
    _g = _parse_pool_json("Here is the pool spec you requested: it's impossible to describe.")
    if _g is not None:
        failures.append(f"P0.83 (G) expected None for prose, got: {_g}")

    # (H) Empty input.
    if _parse_pool_json("") is not None:
        failures.append("P0.83 (H) empty string should parse to None")
    if _parse_pool_json(None) is not None:
        failures.append("P0.83 (H) None input should parse to None")

    # (I) Malformed JSON (truncated).
    if _parse_pool_json('{"columns": {"a": {"bucket": "numeric", "min": 0, "max": 1') is not None:
        failures.append("P0.83 (I) truncated JSON should parse to None")

    if failures:
        print("[SANITY FAIL] P0.83 pool-parser invariants:")
        for f in failures:
            print(f"  {f}")
        return False
    print("[SANITY] P0.83 pool-parser invariants green — all 9 LLM response shapes tolerated")
    return True


